tools.example:
fs = 1000;
d = designfilt('lowpassiir','FilterOrder',8, ...
    'HalfPowerFrequency',100,'SampleRate',fs);
t = (0:1/fs:1-1/fs)';
x = sin(2*pi*50*t) + 0.5*sin(2*pi*300*t);
y = filtfilt(d,x);
fvtool(d)

fs = 1000;
[z,p,k] = butter(6, [40 180]/(fs/2), 'bandpass');
sos = zp2sos(z,p,k);
x = randn(2000,1);
y = sosfilt(sos, x);
freqz(sos, 1024, fs)

fs = 8000;
[z,p,k] = cheby1(5, 0.5, 1500/(fs/2), 'low');
sos = zp2sos(z,p,k);
fvtool(sos)

fs = 2000;
[z,p,k] = cheby2(7, 60, 300/(fs/2));
sos = zp2sos(z,p,k);
freqz(sos, 2048, fs)

fs = 48000;
[z,p,k] = ellip(6, 0.1, 80, 8000/(fs/2));
sos = zp2sos(z,p,k);
fvtool(sos,'Fs',fs)

[b,a] = besself(5, 2*pi*1000);
freqs(b,a)
% Discretize at 10 kHz using a bilinear transform
[bd,ad] = bilinear(b,a,10000);

fs = 1000;
[n,Wn] = buttord(100/(fs/2), 150/(fs/2), 1, 60);
[z,p,k] = butter(n, Wn);
sos = zp2sos(z,p,k);
fprintf('Order = %d\n', n);

fs = 1000;
[n,Ws] = cheb2ord(80/(fs/2), 120/(fs/2), 1, 50);
[z,p,k] = cheby2(n, 50, Ws);
sos = zp2sos(z,p,k);

fs = 1000;
b = fir1(80, [30 80]/(fs/2), 'bandpass', kaiser(81, 6));
x = chirp(0:1/fs:2, 0, 2, 200);
y = filtfilt(b, 1, x);
freqz(b, 1, 1024, fs)

fs = 8000;
[n, fo, ao, w] = firpmord([1500 2000], [1 0], [0.01 0.0001], fs);
b = firpm(n, fo, ao, w);
fprintf('Estimated order: %d\n', n);

fs = 8000;
[n, Wn, beta, ftype] = kaiserord([1000 1200], [1 0], [0.05 0.01], fs);
b = fir1(n, Wn, ftype, kaiser(n+1, beta), 'noscale');
freqz(b, 1, 1024, fs)

[b,g] = sgolay(3, 21);
x = cumsum(randn(500,1));
y = conv(x, g(:,1), 'same');      % smoothed signal
dy = conv(x, factorial(1)*g(:,2), 'same');  % first derivative
plot(1:500, x, 1:500, y)

fs = 1000;
b = fir1(50, 100/(fs/2));
x = randn(5000,1);
zi = zeros(50,1);
y = zeros(size(x));
for k = 1:500:5000
    idx = k:k+499;
    [y(idx), zi] = filter(b, 1, x(idx), zi);
end

fs = 500;
d = designfilt('bandpassiir','FilterOrder',6, ...
    'HalfPowerFrequency1',8,'HalfPowerFrequency2',30,'SampleRate',fs);
x = randn(5000,1);
y = filtfilt(d, x);

b = fir1(2000, 0.2);
x = randn(1e6,1);
tic; y1 = fftfilt(b, x); t1 = toc;
tic; y2 = filter(b, 1, x); t2 = toc;
fprintf('fftfilt %.3fs vs filter %.3fs\n', t1, t2);

fs = 1000;
[z,p,k] = ellip(10, 0.1, 80, 200/(fs/2));
[sos, g] = zp2sos(z, p, k);
x = randn(4000,1);
y = g * sosfilt(sos, x);

fs = 1000;
b = fir1(60, [50 150]/(fs/2), 'bandpass');
[h,f] = freqz(b, 1, 2048, fs);
plot(f, 20*log10(abs(h))); grid on
xlabel('Hz'); ylabel('dB')

[b,a] = butter(4, 2*pi*1000, 's');
w = 2*pi*logspace(1,5,500);
h = freqs(b, a, w);
semilogx(w/(2*pi), 20*log10(abs(h))); grid on

fs = 1000;
[b,a] = butter(4, 100/(fs/2));
[h,t] = impz(b, a, 200, fs);
stem(t, h); xlabel('Time (s)')

fs = 1000;
d = designfilt('lowpassfir','FilterOrder',40,'CutoffFrequency',100,'SampleRate',fs);
stepz(d)

fs = 1000;
[b,a] = ellip(6, 0.5, 60, 100/(fs/2));
bf = fir1(60, 100/(fs/2));
[g1,f] = grpdelay(b, a, 1024, fs);
[g2,~] = grpdelay(bf, 1, 1024, fs);
plot(f, g1, f, g2); legend('elliptic','FIR')

b = fir1(40, 0.3);
[phi, w] = phasez(b, 1, 512);
plot(w/pi, phi); xlabel('\omega/\pi'); ylabel('Phase (rad)')

fs = 1000;
[z,p,k] = butter(6, 100/(fs/2));
zplane(z, p); title('Butterworth poles/zeros')
fprintf('Stable: %d\n', all(abs(p) < 1));

fs = 48000;
[z,p,k] = ellip(12, 0.05, 90, 6000/(fs/2));
[sos, g] = zp2sos(z, p, k, 'down', 'inf');
y = g * sosfilt(sos, randn(10000,1));

[b,a] = cheby1(8, 0.5, 0.25);
[sos, g] = tf2sos(b, a);
y = g * sosfilt(sos, randn(2000,1));

[z,p,k] = butter(6, 0.2);
[sos, g] = zp2sos(z, p, k);
[b, a] = sos2tf(sos, g);
max(abs(freqz(b,a,512) - freqz(sos,512)))

[b,a] = butter(5, 0.3);
[z,p,k] = tf2zp(b, a);
zplane(z, p);
fprintf('Max |pole| = %.4f\n', max(abs(p)));

% 50 Hz notch at fs = 1000 Hz
fs = 1000; f0 = 50; r = 0.98;
w0 = 2*pi*f0/fs;
z = [exp(1j*w0); exp(-1j*w0)];
p = r*z;
[b,a] = zp2tf(z, p, 1);
freqz(b, a, 2048, fs)

fs = 1000;
t = (0:1/fs:1-1/fs)';
x = sin(2*pi*20*t) + sin(2*pi*250*t);
y = lowpass(x, 50, fs, 'Steepness', 0.95);
lowpass(x, 50, fs)   % plot to inspect

fs = 250;
t = (0:1/fs:10-1/fs)';
ecg = sin(2*pi*1.2*t) + 0.5*t;   % signal plus drift
clean = highpass(ecg, 0.5, fs, 'ImpulseResponse', 'iir');

fs = 256;
x = randn(5*fs, 1);
alpha = bandpass(x, [8 12], fs, 'Steepness', 0.9);
bandpass(x, [8 12], fs)

x = sin(2*pi*(0:999)/100)';
x(randperm(1000, 30)) = 5;    % add spikes
y = medfilt1(x, 7, [], 1, 'truncate');
plot(1:1000, x, 1:1000, y)

t = linspace(0, 1, 1000)';
x = exp(-((t-0.5)/0.02).^2) + 0.05*randn(1000,1);
y = sgolayfilt(x, 3, 41);
plot(t, x, t, y, 'LineWidth', 1.2)

fs = 1000;
bf = fir1(60, 100/(fs/2));
[z,p,k] = butter(6, 100/(fs/2));
sos = zp2sos(z,p,k);
fvtool(bf, 1, sos, 'Fs', fs);
legend('FIR-60','Butterworth-6')
